@Component("loan-handler")
@ProcessingGroup("loan-processing-group")
public class LoanEventHandler {
	
	// core constructor
	LoanEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLoanEvent
     */
    @EventHandler
    public void handle( CreateLoanEvent event) {
        entityManager.persist(new Loan(event.getLoanId(), event.getLoanNumber(), event.getPrincipal(), event.getInterestRate(), event.getOriginationDate(), event.getMaturityDate(), event.getCustomer(), event.getSchedule(), event.getCollateral(), event.getTransactions(), event.getRateType(), event.getStatus()));
    }

    /*
     * @param	event UpdateLoanEvent
     */
    @EventHandler
    public Loan handle( UpdateLoanEvent event) {
    	entityManager.merge(new Loan(event.getLoanId(), event.getLoanNumber(), event.getPrincipal(), event.getInterestRate(), event.getOriginationDate(), event.getMaturityDate(), event.getCustomer(), event.getSchedule(), event.getCollateral(), event.getTransactions(), event.getRateType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteLoanEvent
     */
    @EventHandler
    public void on( DeleteLoanEvent event) {
    	Loan entity = new Loan();
   
    	// ------------------------------------------
    	// apply the LoanId
    	// ------------------------------------------
    	entity.setLoanId( event.getLoanId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LoanRepository loanEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LoanEventHandler.class.getName());

}
